            prerelease_ids = prerelease.split('.')
        else:
            prerelease_ids = None

        return (major, minor, patch, prerelease_ids)

    def compare_prerelease(pre1, pre2):
        # None means no pre-release (higher precedence)
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # no pre-release sorts after pre-release
        if pre2 is None:
            return -1  # pre-release sorts before no pre-release

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
