                # Numeric sorts before non-numeric
                return -1
            elif is_num2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric: compare lexically
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # If all compared identifiers are equal, fewer identifiers sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        return 0

    def sort_key(version_str):
        major, minor, patch, prerelease_ids = parse_version(version_str)
        # Return tuple that sorts correctly: (major, minor, patch, prerelease_tuple)
        # For prerelease: None should sort after anything, so we use a special tuple
        if prerelease_ids is None:
            # No prerelease: use (1,) to sort after prerelease versions
            return (major, minor, patch, (1,))
        else:
            # Has prerelease: use (0, ids_tuple) to sort before no-prerelease
