                    normalized_ids.append((0, int(identifier)))
                else:
                    normalized_ids.append((1, identifier))
            return (major, minor, patch, (0, tuple(normalized_ids)))

    # Use stable sort to preserve input order for equal versions
    return sorted(versions, key=sort_key)

